                 .canonicalUrl(request.getRequestURL().toString())
                 .siteName(seoSiteName)
                 .imageUrl(seoImage)
                 .ogType(seoOgType)
                 .twitterCard(seoTwitterCard)
                 .twitterSite(seoTwitterSite)
                 .openGraph(true)
                 .twitter(true)
                 .structuredData(seoStructuredData)
                 .build();
